class Solution:
    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':
        oldToNew = {}

        cur = head
        while cur:
            oldToNew[cur] = Node(cur.val)
            cur = cur.next

        cur = head
        while cur:
            copy = oldToNew[cur]
            copy.next = oldToNew.get(cur.next)
            copy.random = oldToNew.get(cur.random)
            cur = cur.next

        return oldToNew.get(head)

