class Solution:
    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':
        if not head:
            return None

        originals = []
        node = head
        while node:
            originals.append(node)
            node = node.next

        copies = [Node(n.val) for n in originals]

        for i, n in enumerate(originals):
            copies[i].next = copies[i + 1] if i + 1 < len(originals) else None
            if n.random is not None:
                j = originals.index(n.random)
                copies[i].random = copies[j]

        return copies[0]
